// Product flows derived from the supplied walkthrough. Values remain editable demo configuration.
paths.chat='M21 11a8 8 0 0 1-8 8H5l-4 3V11a8 8 0 0 1 8-8h4a8 8 0 0 1 8 8 M6 9h10 M6 13h6';paths.pin='m8 3 8 0-1 6 4 4H5l4-4-1-6 M12 13v9';paths.send='m3 3 18 9-18 9 4-9-4-9 M7 12h14';paths.spark='m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7';
let flowStep=1,flowDraft={name:'',description:'',logo:'chain',tags:[],policy:'open',minVolume:'',minVip:'',minAssets:'',rules:'',announcement:''},missionTab='daily';
state.forums=state.forums||{};state.checkins=state.checkins||{};
const demoPoints=g=>g.points??Math.round(g.volume*380000);
const logoNames=['chain','stellar','unisat','alpha','nova','delta'];
state.drafts.forEach(g=>{delete g.capacity;if(g.volume===0&&g.level===1){g.isNew=true;g.tier="New";g.points=0}});baseGuilds.forEach(g=>delete g.capacity);
function memberContext(){const preview=routeQuery.get('preview')==='1';const g=preview?guildById('unisat'):state.membership&&guildById(state.membership.id);return {preview,g}}
function previewSuffix(preview){return preview?'?preview=1':''}
function featureLinks(g,preview){return `<div class="flow-feature-links">${link('arena'+previewSuffix(preview),`<span class="feature-orb">${icon('swords')}</span><span><small>THE TEAM COMPETITION</small><strong>Guild Battle</strong></span>${arrow()}`)}${link('forum/'+g.id+previewSuffix(preview),`<span class="feature-orb">${icon('chat')}</span><span><small>YOUR COMMUNITY SPACE</small><strong>Guild Forum</strong></span>${arrow()}`)}</div>`}
function progression(g,preview){const percent=g.isNew?0:85;return `<section class="workspace-panel progression-panel">${sectionTitle('A shared journey. The next chapter.','Guild progression · Illustrative design')}<div class="progression-layout"><div class="progression-identity"><span>${icon('shield')}</span><small>CURRENT GUILD STATUS</small><strong>${g.isNew?'New guild':g.tier}</strong><p>${g.isNew?'Your first chapter starts here.':'Every contribution moves the team.'}</p></div><div class="progression-ring"><svg viewBox="0 0 160 160" role="img" aria-label="${percent}% illustrative guild progression"><circle cx="80" cy="80" r="65" pathLength="100"/><circle cx="80" cy="80" r="65" pathLength="100" stroke-dasharray="${percent} 100"/></svg><div><small>TEAM PROGRESS</small><strong>${percent}%</strong><span>${g.isNew?'THE BEGINNING':'NEXT CHAPTER'}</span></div></div><div class="progression-goals"><div><span>${icon('chart')}</span><p><strong>${g.isNew?'Your first trades':'Trading together'}</strong><small>${g.isNew?'Trading integration comes later':'Illustrative volume milestone'}</small></p><b>${g.isNew?'—':'82%'}</b></div><div><span>${icon('users')}</span><p><strong>A growing community</strong><small>Participation, without a member limit</small></p><b>${g.members.toLocaleString()}</b></div><div><span>${icon('target')}</span><p><strong>Shared missions</strong><small>${g.isNew?'Explore your first team objectives':'Teamwork makes the difference'}</small></p><b>${g.isNew?'0':'3'}</b></div><button class="secondary" data-share="${g.id}">${icon('users')} Invite your circle ${arrow()}</button></div></div><div class="panel-footnote">Progression thresholds and tiers are demonstration values. Final parameters will be designed separately.</div></section>`}
const missionData={daily:[['volume','Daily volume mission','Contribute to today’s shared trading objective.','chart',80,'Trade now','Points + USDT','02h 45m'],['checkin','Daily check-in','Show up for your community. Every connection counts.','users',65,'Check in','Points + USDT','06h 20m'],['pairs','Daily pair challenge','Explore a shared focus across eligible trading pairs.','target',42,'Trade now','Points','08h 10m']],weekly:[['community','Grow the trading circle','Bring new perspectives into your community.','users',75,'Invite friends','Points + USDT','3d 12h'],['sprint','Weekly volume sprint','A collective trading milestone for your guild.','chart',58,'Trade now','Points + USDT','4d 02h'],['consistency','Consistency counts','Keep your community connected throughout the week.','target',46,'View team','Points','4d 02h']],event:[['event-pairs','The event challenge','A focused team objective for the competition window.','swords',20,'Trade now','Points + collectible','5d 20h'],['ranking','Make your mark','Bring your team into the guild leaderboard conversation.','trophy',34,'View ranking','Points + guild banner','6d 08h'],['referrals','A bigger perspective','Introduce your trading circle to the guild.','users',15,'Invite friends','Points','6d 08h']]};
function missionBoard(g,preview){const isNew=g.isNew;return `<section class="workspace-panel mission-board">${sectionTitle('Guild missions','Individual actions. Collective momentum.',`<span class="outline-tag">DEMO OBJECTIVES</span>`)}<div class="mission-period-tabs" role="group" aria-label="Mission period">${[['daily','Daily'],['weekly','Weekly'],['event','Event']].map(([id,t])=>`<button data-mission-tab="${id}" class="${missionTab===id?'selected':''}">${t}<span>${missionData[id].length}</span></button>`).join('')}</div><div class="mission-list">${missionData[missionTab].map(([id,t,desc,ic,progress,action,reward,time])=>{const checked=id==='checkin'&&state.checkins[g.id]===new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Hong_Kong'});const pct=checked?100:isNew?0:progress;return `<article class="mission-row"><span class="mission-symbol">${icon(ic)}</span><div class="mission-details"><div class="mission-title"><h3>${t}</h3><span>${checked?'LOCAL CHECK-IN SAVED':isNew?'READY TO BEGIN':'IN PROGRESS · SAMPLE'}</span></div><p>${desc}</p><div class="mission-bar"><i style="width:${pct}%"></i></div><div class="mission-row-meta"><span>${icon('gift')} ${reward} <em>· terms to be set</em></span><span>${pct}%</span></div></div><div class="mission-row-action"><button class="${checked?'secondary':'primary'}" data-mission-action="${id}" data-context-guild="${g.id}" ${checked?'disabled':''}>${checked?'Checked in':action}${checked?icon('check'):arrow()}</button><small>${icon('clock')} ${time} <span>sample</span></small></div></article>`}).join('')}</div><div class="panel-footnote">Mission progress, rewards and remaining times are illustrative. Local check-ins do not grant points or funds.</div></section>`}
dashboardOverview=function(g,preview){const actualName=preview?'Demo Trader':state.membership?.name||'Trader';return `<div class="welcome-strip"><div><h2>Welcome ${preview?'to the team':`back, ${escapeHtml(actualName)}`}.</h2><p>Your guild is more than a ranking. It’s the people moving with you.</p></div><button class="secondary compact" data-flow-trade>Trade to contribute ${arrow()}</button></div>`+kpis([['GUILD MEMBERS',g.members.toLocaleString(),'A community without a member limit','users'],['14D GUILD VOLUME',money(g.volume),'Illustrative team trading activity','chart'],['GUILD POINTS',demoPoints(g).toLocaleString(),'Demo team contribution points','trophy'],['ACTIVE MEMBERS',Math.round(g.members*g.activity/100).toLocaleString(),'Illustrative participation','target']])+featureLinks(g,preview)+progression(g,preview)+`<div id="dashboard-missions">${missionBoard(g,preview)}</div><div class="content-grid profile-bottom"><section class="workspace-panel">${sectionTitle('From your guild','The conversation starts here',link('forum/'+g.id+previewSuffix(preview),'Open forum '+arrow(),'text-button'))}<div class="noticeboard"><span class="pinned-tag">GUILD ANNOUNCEMENT</span><h3>${g.isNew?'Welcome to your first chapter.':'Different perspectives. One team.'}</h3><p>${escapeHtml(g.announcement||'Share your perspective, support your teammates and help build a thoughtful trading community.')}</p><div class="forum-teaser"><span class="avatar">${escapeHtml(actualName.slice(0,1))}</span><a href="#/forum/${g.id}${previewSuffix(preview)}">What’s on your mind? ${icon('chat')}</a></div></div></section><section class="workspace-panel">${sectionTitle('Team contributors','Illustrative guild contribution roster',link('my-guild/members'+previewSuffix(preview),'View team '+arrow(),'text-button'))}${contributorList(g)}</section></div>`};
missionsPage=function(g,preview){return `<div class="missions-summary"><div><span class="page-eyebrow">SHOW UP. CONTRIBUTE. GROW TOGETHER.</span><h2>Small actions. A shared story.</h2><p>Daily consistency, weekly momentum and event ambition.</p></div><div>${icon('gift')}<span>YOUR CLAIMABLE REWARDS<strong>—</strong><small>Rewards are not connected in this prototype</small></span></div></div><div id="dashboard-missions">${missionBoard(g,preview)}</div><div class="workspace-panel reward-ledger">${sectionTitle('Reward history','A clear record of future rewards')}<div class="page-empty">${icon('gift')}<h2>Your story is just getting started.</h2><p>No reward transactions or claims are connected to this demo.</p></div></div>`};
const prevProfileOverview=profileOverview;
profileOverview=function(g){return `<section class="workspace-panel entry-panel">${sectionTitle('Your place in the team','Membership made clear',`<span class="outline-tag">${g.policy==='open'?'INSTANT JOIN':'APPROVAL REQUIRED'}</span>`)}<div class="entry-checks"><div>${icon('users')}<span><strong>${g.policy==='open'?'An open trading circle':'A thoughtful introduction'}</strong><small>${g.policy==='open'?'Join directly through the confirmation step.':'Share an introduction for guild leadership.'}</small></span><b>No member limit</b></div><div>${icon('shield')}<span><strong>One shared team</strong><small>Keep one active demo guild membership at a time.</small></span><b>${state.membership&&state.membership.id!==g.id?'Already in a guild':state.membership?'Your current guild':'Ready to explore'}</b></div></div><details class="entry-config"><summary>View entry settings <span>Demonstration parameters</span></summary><div>${[['14D trading volume',g.minVolume?Number(g.minVolume).toLocaleString()+' USDT':'Not set'],['Account level',g.minVip?'VIP '+g.minVip+'+':'Not set'],['Assets / margin',g.minAssets?Number(g.minAssets).toLocaleString()+' USDT':'Not set']].map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><p>These settings demonstrate the flow. Eligibility is not checked against a production account.</p></details></section>`+prevProfileOverview(g).replace("<div class=\"about-note\">",'<div class="about-note">')};
showJoin=function(id){const g=guildById(id);if(!g)return;if(state.membership?.id===id){showMyGuild();return}if(state.membership){open(`<div class="modal-eyebrow">ONE TEAM AT A TIME</div><h2>You already have a trading circle.</h2><p>You’re a demo member of ${escapeHtml(guildById(state.membership.id)?.name||'another guild')}. Manage your current membership before joining another team.</p><div class="modal-actions"><button class="secondary" data-guild="${id}">Back to profile</button><button class="primary" data-action="myguild">Open My Guild ${arrow()}</button></div>`);return}if(state.pending.includes(id)){showMyGuild();return}open(`<div class="join-flow"><div class="modal-eyebrow">${g.policy==='open'?'YOUR NEXT CHAPTER':'INTRODUCE YOURSELF'}</div><div class="join-flow-emblem"><img src="${emblem(g)}" alt=""></div><h2>${g.policy==='open'?'Join':'Apply to'} ${escapeHtml(g.name)}?</h2><p>${g.policy==='open'?'A shared ambition starts with your first step.':'Tell the team a little about the perspective you bring.'}</p><div class="join-summary"><div>${tier(g)}<span>${g.members.toLocaleString()} members</span></div><p>${escapeHtml(g.description)}</p><div><span>Your role</span><strong>Member</strong></div></div><form id="flow-join-form" class="form" data-id="${id}"><label for="flow-trader-name">Your demo trader name</label><input id="flow-trader-name" name="name" required maxlength="30" placeholder="Your name in the community" value="${escapeHtml(state.profileName||'')}" autofocus>${g.policy==='approval'?'<label for="flow-intro">Your introduction</label><textarea id="flow-intro" name="intro" required maxlength="300" rows="3" placeholder="What brings you to this guild?"></textarea>':''}<div class="join-disclaimer">${icon('shield')} One active guild at a time. This demo saves your ${g.policy==='open'?'membership':'application'} only on this browser.</div><div class="modal-actions"><button class="secondary" type="button" data-guild="${id}">Not now</button><button class="primary" type="submit">${g.policy==='open'?'Confirm join':'Save application'} ${arrow()}</button></div></form></div>`)};
function showWelcome(g,created=false){open(`<div class="welcome-modal"><div class="modal-eyebrow">${created?'YOUR VISION HAS A HOME':'YOU BELONG HERE'}</div><div class="welcome-emblem"><div></div><img src="${emblem(g)}" alt=""></div><h2>${created?'Your guild.<br>Your next chapter.':'Welcome to<br>'+escapeHtml(g.name)+'.'}</h2><p>${created?'Your trading circle is ready to grow. Set the tone and bring your people together.':'A new perspective joins the team. Find your place, explore the missions and meet your guild.'}</p><span class="member-pill">${icon('check')} ${created?'Guild leader':'Guild member'} · Local demo</span><button class="primary" data-action="myguild">Enter Guild Dashboard ${arrow()}</button><small>Saved on this browser. No on-chain transaction.</small></div>`)}
arenaPage=function(tab='overview'){const ctx=memberContext(),g=ctx.g||guildById('unisat'),sample=ctx.preview||!ctx.g,first=g.isNew?0:6800000,second=6200000,total=first+second,share=total?first/total*100:0;const milestones=[2500000,5000000,7500000,10000000,25000000,50000000,75000000,100000000];return breadcrumb('Guild Battle')+heading('TRADE AS INDIVIDUALS. COMPETE AS ONE.','YOUR TEAM.<br><span>YOUR SHARED EDGE.</span>','The match, the milestones and the people moving your guild forward.',`<span class="battle-demo-badge">${icon('swords')} DEMO MATCH</span>`)+`<section class="arena-match battle-flow-match"><div class="match-top"><span>${icon('swords')} WEEKLY GUILD BATTLE</span><span class="outline-tag">MATCH PREVIEW · NO LIVE EVENT</span></div><div class="match-contenders"><a href="#/guild/${g.id}"><span class="match-team-tier">YOUR GUILD</span><img src="${emblem(g)}" alt=""><h2>${escapeHtml(g.name)}</h2><p>CURRENT MATCH VOLUME</p><strong>${compactMoney(first)} <small>USDT</small></strong></a><div class="match-versus"><span>GUILD VS GUILD</span><strong>VS</strong><small>ONE SHARED AMBITION</small></div><div class="opponent-team"><span class="match-team-tier">THE CHALLENGER</span><img src="assets/delta.webp" alt=""><h2>Delta Wolves</h2><p>CURRENT MATCH VOLUME</p><strong>${compactMoney(second)} <small>USDT</small></strong></div></div><div class="battle-score"><div><strong>${share.toFixed(1)}%</strong><span>${(100-share).toFixed(1)}%</span></div><div class="battle-score-track"><i style="width:${share}%"></i></div><p>${first>=second?'Your team leads by':'The gap to the challenger is'} <strong>${compactMoney(Math.abs(first-second))} USDT</strong></p></div><div class="battle-match-footer"><span>${icon('clock')} 23h 43m <small>Illustrative remaining time</small></span><div><button class="text-button" data-battle-rules>View battle rules ${arrow()}</button><button class="primary" data-flow-trade>Trade to contribute ${arrow()}</button></div></div></section><div class="page-tabs"><a href="#/arena${previewSuffix(ctx.preview)}" class="${tab==='overview'?'selected':''}">Match overview</a><a href="#/arena/format${previewSuffix(ctx.preview)}" class="${tab==='format'?'selected':''}">Battle format</a><a href="#/arena/rewards${previewSuffix(ctx.preview)}" class="${tab==='rewards'?'selected':''}">Reward concept</a><span>DEMONSTRATION VALUES</span></div>${tab==='format'?arenaFormat():tab==='rewards'?arenaRewards():`<section class="workspace-panel battle-milestones">${sectionTitle('Every milestone belongs to the team','Illustrative combined match volume · Reward terms to be designed',`<span class="outline-tag">${compactMoney(total)} COMBINED</span>`)}<div class="milestone-scroll"><div class="milestone-rail">${milestones.map((v,i)=>`<div class="${total>=v?'unlocked':''}"><strong>${compactMoney(v)}</strong><span>${icon(total>=v?'check':'shield')}</span><small>MILESTONE ${String(i+1).padStart(2,'0')}</small><p>${total>=v?'Reached':'Ahead of the team'}</p></div>`).join('')}</div></div></section><div class="content-grid battle-details"><section class="workspace-panel personal-battle">${sectionTitle(sample?'A member’s contribution':'Your contribution',sample?'Sample profile · Demonstration values':'Your local demo profile')}<div class="personal-battle-heading"><span class="avatar">${sample?'D':escapeHtml((state.membership?.name||'T').slice(0,1))}</span><div><strong>${sample?'Demo Trader':escapeHtml(state.membership?.name||'Trader')}</strong><small>${sample?'SAMPLE CONTRIBUTOR':'GUILD MEMBER'}</small></div><span class="sample-label">${sample?'PREVIEW':'LOCAL DEMO'}</span></div><div class="personal-battle-stats"><div><span>Battle volume</span><strong>${sample?'$128.50K':'$0.00'}</strong></div><div><span>Contribution rank</span><strong>${sample?'#08':'—'}</strong></div><div><span>Estimated reward share</span><strong>— <small>Terms to be set</small></strong></div></div><div class="panel-footnote">No reward is claimable or guaranteed. These views demonstrate the participation flow.</div></section><section class="workspace-panel">${sectionTitle('The people behind the progress','Sample battle contributors')}${battleContributors(g,first)}</section></div>`}`};
function forumPage(id){const g=guildById(id)||memberContext().g||guildById('unisat');const preview=routeQuery.get('preview')==='1'||state.membership?.id!==g.id;const owner=!preview&&state.membership?.role==='owner';const local=state.forums[g.id]||[];return breadcrumb(`${link('my-guild'+previewSuffix(preview),'My Guild')}<span>/</span>Guild Forum`)+`<div class="forum-heading"><div><span class="page-eyebrow">YOUR PEOPLE. YOUR CONVERSATION.</span><h1 tabindex="-1">${escapeHtml(g.name)} <span>FORUM.</span></h1><p>Ideas, shared objectives and the conversations that build a team.</p></div>${link('my-guild'+previewSuffix(preview),'Back to Dashboard '+arrow(),'secondary button')}</div><div class="forum-mode">${icon('chat')} <strong>${preview?'CHAT PREVIEW':'YOUR LOCAL GUILD SPACE'}</strong><span>Messages stay on this browser. No messages are sent to other people.</span></div><section class="forum-workspace"><div class="forum-chat"><div class="forum-channel-header"><div>${icon('chat')} <strong>Guild lounge</strong><span>COMMUNITY CHANNEL</span></div><span>${local.length} local message${local.length===1?'':'s'}</span></div><div class="forum-pinned"><span>${icon('pin')}</span><div><small>PINNED BY GUILD LEADERSHIP</small><p>${escapeHtml(g.announcement||'Share your perspective, support your teammates and keep the conversation thoughtful.')}</p></div>${owner?'<button class="text-button" data-edit-pin>Edit</button>':'<span class="sample-label">GUILD NOTICE</span>'}</div><div class="chat-scroll" id="chat-scroll"><div class="chat-date">THE CONVERSATION STARTS HERE</div>${!g.isNew?`<div class="chat-message"><span class="avatar avatar-1">S</span><div><div class="chat-message-meta"><strong>SatoshiWave</strong><span>Guild leader · Sample message</span></div><p>Welcome to the team. What’s one perspective you’re bringing to the markets this week?</p></div></div><div class="chat-message"><span class="avatar avatar-2">B</span><div><div class="chat-message-meta"><strong>BlueHorizon</strong><span>Vice leader · Sample message</span></div><p>A good reminder: share the reasoning behind an idea. Different perspectives make the community stronger.</p></div></div>`:`<div class="chat-start">${icon('spark')}<h2>A new space. A shared beginning.</h2><p>Set the tone with your first local message.</p></div>`}${local.map(m=>`<div class="chat-message own-message"><div><div class="chat-message-meta"><strong>${escapeHtml(m.name)}</strong><span>${escapeHtml(m.time)} · Saved locally</span></div><p>${escapeHtml(m.text).replace(/\n/g,'<br>')}</p></div><span class="avatar">${escapeHtml(m.name.slice(0,1))}</span></div>`).join('')}</div><form class="chat-composer" id="forum-form" data-id="${g.id}"><label class="sr-only" for="chat-message">Message your demo guild</label><textarea id="chat-message" name="message" rows="1" maxlength="2000" required placeholder="Share a thought with your guild…"></textarea><button class="primary" type="submit" aria-label="Save message locally">${icon('send')}</button></form><div class="chat-composer-caption"><span>Enter to post · Shift + Enter for a new line</span><span>LOCAL DEMO</span></div></div><aside class="forum-members"><div><h2>The trading circle</h2><span>${g.members.toLocaleString()} guild members</span></div><p>${g.isNew?'Your local guild roster':'Sample roster · Not the complete member list'}</p><div class="forum-member-list">${roster(g).map((m,i)=>`<div><span class="avatar avatar-${i%4}">${escapeHtml(m.initial)}</span><span><strong>${escapeHtml(m.name)}</strong><small>${m.isYou?'YOU · ':''}${m.role==='Co-leader'?'Vice leader':m.role}</small></span>${i<2?icon('shield'):''}</div>`).join('')||'<p>Your community starts with you.</p>'}</div><div class="forum-member-foot">${icon('shield')} Different strategies.<br>Shared respect.</div></aside></section>`}
function collectFlowDraft(){const form=$('#flow-create-form');if(!form)return;const f=new FormData(form);['name','description','policy','minVolume','minVip','minAssets','rules','announcement'].forEach(k=>{if(f.has(k))flowDraft[k]=String(f.get(k)).trim()})}
const tagOptions=['Beginner Friendly','High Volume','Perp Traders','RWA Traders','KOL Community','GenZ','Competitive','Casual','Invite Only'];
showCreate=function(){if(state.membership){navigate('my-guild');toast('Manage your current membership before creating a new guild.');return}flowStep=1;flowDraft={name:'',description:'',logo:'chain',tags:[],policy:'open',minVolume:'',minVip:'',minAssets:'',rules:'',announcement:''};navigate('create')};actions.create=showCreate;
function creationPreview(){return `<aside class="creation-preview"><span class="page-eyebrow">YOUR GUILD, TAKING SHAPE</span><div class="creation-preview-art"><img id="creation-logo-preview" src="${flowDraft.logoData||'assets/'+flowDraft.logo+'.webp'}" alt="Guild emblem preview"></div><h2 id="creation-name-preview">${escapeHtml(flowDraft.name||'Your guild name')}</h2><p id="creation-description-preview">${escapeHtml(flowDraft.description||'A shared ambition deserves a place to grow.')}</p><div class="style-tags" id="creation-tags-preview">${flowDraft.tags.map(t=>`<span>${escapeHtml(t)}</span>`).join('')||'<span>Your community</span>'}</div><div class="creation-preview-details"><div><span>Your role</span><strong>Guild leader</strong></div><div><span>Members</span><strong>You’re the first</strong></div><div><span>Membership</span><strong>${flowDraft.policy==='open'?'Instant join':'Approval required'}</strong></div></div><div class="creation-preview-note">${icon('shield')} Make it yours.<br>You can refine the settings later.</div></aside>`}
wizardPage=function(){if(state.membership)return `<div class="page-empty">${icon('shield')}<h1>Your team is already here.</h1><p>Manage your current membership before starting another guild.</p>${link('my-guild','Open My Guild '+arrow(),'primary button')}</div>`;return breadcrumb('Create Guild')+heading('YOUR VISION. YOUR PEOPLE.','BUILD SOMETHING<br><span>WORTH BELONGING TO.</span>','A name. A shared purpose. A place for your trading circle.')+`<div class="creation-steps">${[['Identity','Give your team a name'],['Membership','Set the way in'],['Rules & launch','Make everyone feel at home']].map(([t,p],i)=>`<div class="${flowStep===i+1?'active':flowStep>i+1?'complete':''}"><span>${flowStep>i+1?icon('check'):'0'+(i+1)}</span><div><strong>${t}</strong><small>${p}</small></div></div>`).join('')}</div><div class="creation-layout"><section class="workspace-panel creation-form-panel"><form id="flow-create-form" class="form"><div class="page-eyebrow">STEP 0${flowStep} / 03</div>${flowStep===1?`<h2>Every guild starts with a story.</h2><p>Help your people recognize the community you’re building.</p><label for="flow-guild-name">Guild name</label><input id="flow-guild-name" name="name" required minlength="3" maxlength="28" value="${escapeHtml(flowDraft.name)}" placeholder="A name your team will stand behind"><label>Guild emblem <span>Choose a preset or upload your own</span></label><div class="emblem-options">${logoNames.map(n=>`<button type="button" data-flow-logo="${n}" class="${flowDraft.logo===n&&!flowDraft.logoData?'selected':''}" aria-label="Choose ${n} emblem" aria-pressed="${flowDraft.logo===n&&!flowDraft.logoData}"><img src="assets/${n}.webp" alt=""></button>`).join('')}</div><label class="logo-upload" for="guild-logo-upload">${icon('shield')} Upload an emblem <span>PNG, JPG or WebP · up to 2 MB</span><input id="guild-logo-upload" type="file" accept="image/png,image/jpeg,image/webp"></label><label for="flow-description">Guild description</label><textarea id="flow-description" name="description" required minlength="10" maxlength="180" rows="3" placeholder="What brings your traders together?">${escapeHtml(flowDraft.description)}</textarea><label>Guild tags <span>Choose the labels that feel like your team</span></label><div class="tag-options">${tagOptions.map(t=>`<button type="button" data-flow-tag="${t}" class="${flowDraft.tags.includes(t)?'selected':''}" aria-pressed="${flowDraft.tags.includes(t)}">${t}</button>`).join('')}</div>`:flowStep===2?`<h2>Great communities start with a clear welcome.</h2><p>Choose how traders become part of the team. Fine-tune the parameters later.</p><label>How do people join?</label><div class="policy-options"><label class="policy-option ${flowDraft.policy==='open'?'chosen':''}"><input type="radio" name="policy" value="open" ${flowDraft.policy==='open'?'checked':''}><span>${icon('users')}<strong>Instant join</strong><small>A direct path into your community.</small></span></label><label class="policy-option ${flowDraft.policy==='approval'?'chosen':''}"><input type="radio" name="policy" value="approval" ${flowDraft.policy==='approval'?'checked':''}><span>${icon('shield')}<strong>Approval required</strong><small>A personal introduction before joining.</small></span></label></div><div class="membership-note">${icon('users')} A community can keep growing. There is no member limit.</div><details class="optional-parameters" ${flowDraft.minVolume||flowDraft.minVip||flowDraft.minAssets?'open':''}><summary>Optional entry settings <span>Adjust later</span></summary><p>Explore the settings layout. These values do not enforce production eligibility.</p><label for="entry-volume">Minimum 14D trading volume <span>USDT</span></label><input id="entry-volume" name="minVolume" type="number" min="0" value="${escapeHtml(flowDraft.minVolume)}" placeholder="Not set"><div class="preset-buttons">${[0,10000,50000,100000].map(v=>`<button type="button" data-entry-preset="minVolume" data-value="${v||''}">${v?v.toLocaleString():'Not set'}</button>`).join('')}</div><div class="row"><div><label for="entry-vip">Minimum account level</label><select name="minVip" id="entry-vip">${[['','Not set'],['1','VIP 1+'],['2','VIP 2+'],['3','VIP 3+']].map(([v,t])=>`<option value="${v}" ${flowDraft.minVip===v?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="entry-assets">Minimum assets / margin</label><input id="entry-assets" name="minAssets" type="number" min="0" value="${escapeHtml(flowDraft.minAssets)}" placeholder="Not set · USDT"></div></div></details>`:`<h2>Set the tone. Start the story.</h2><p>Give your community a clear direction and a warm welcome.</p><label for="flow-rules">Guild rules <span>Optional</span></label><textarea id="flow-rules" name="rules" maxlength="1000" rows="3" placeholder="What makes this a good community to be part of?">${escapeHtml(flowDraft.rules)}</textarea><label for="flow-announcement">Welcome announcement <span>Optional</span></label><textarea id="flow-announcement" name="announcement" maxlength="1000" rows="3" placeholder="Your first message to the team…">${escapeHtml(flowDraft.announcement)}</textarea><div class="launch-summary"><div><span>Membership</span><strong>${flowDraft.policy==='open'?'Instant join':'Approval required'}</strong></div><div><span>Entry settings</span><strong>${flowDraft.minVolume||flowDraft.minVip||flowDraft.minAssets?'Custom demo settings':'Refine later'}</strong></div><div><span>Your role</span><strong>Guild leader</strong></div></div><label class="check"><input name="ack" type="checkbox" required><span>I understand this creates a local demo guild. No production guild, transaction or fee is involved.</span></label>`}<div class="wizard-controls">${flowStep>1?'<button class="secondary" type="button" data-flow-prev>Back</button>':link('discover','Cancel','wizard-cancel')}${flowStep<3?'<button class="primary" type="button" data-flow-next>Continue '+arrow()+'</button>':'<button class="primary" type="submit">Create your guild '+arrow()+'</button>'}</div></form></section>${creationPreview()}</div>`};
const originalSettingsPage=settingsPage;
settingsPage=function(g,preview){const owner=!preview&&state.membership?.role==='owner'&&g.isNew;return originalSettingsPage(g,preview)+`<section class="workspace-panel flow-settings-extra">${sectionTitle('Community direction','The rules, welcome and optional entry settings behind your guild')}<form id="flow-details-form" class="form" data-id="${g.id}"><div class="row"><div><label for="setting-rules">Guild rules</label><textarea id="setting-rules" name="rules" maxlength="1000" rows="4" ${owner?'':'disabled'}>${escapeHtml(g.rules||'Keep the conversation thoughtful. Share ideas with context and respect your teammates.')}</textarea></div><div><label for="setting-announcement">Guild announcement</label><textarea id="setting-announcement" name="announcement" maxlength="1000" rows="4" ${owner?'':'disabled'}>${escapeHtml(g.announcement||'Welcome to the guild. Different perspectives make a stronger community.')}</textarea></div></div><div class="parameter-grid"><div><label for="setting-min-volume">Minimum 14D volume · USDT</label><input id="setting-min-volume" name="minVolume" type="number" min="0" value="${escapeHtml(g.minVolume||'')}" placeholder="Not set" ${owner?'':'disabled'}></div><div><label for="setting-min-vip">Minimum account level</label><select id="setting-min-vip" name="minVip" ${owner?'':'disabled'}>${[['','Not set'],['1','VIP 1+'],['2','VIP 2+'],['3','VIP 3+']].map(([v,t])=>`<option value="${v}" ${g.minVip===v?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="setting-min-assets">Minimum assets · USDT</label><input id="setting-min-assets" name="minAssets" type="number" min="0" value="${escapeHtml(g.minAssets||'')}" placeholder="Not set" ${owner?'':'disabled'}></div></div><div class="settings-save"><span>Parameters are illustrative. There is no member limit.</span>${owner?'<button class="primary" type="submit">Save community settings</button>':'<span class="sample-label">MANAGED BY GUILD LEADERSHIP</span>'}</div></form></section>`};
function updatePreview(){const n=$('#creation-name-preview'),d=$('#creation-description-preview'),t=$('#creation-tags-preview'),img=$('#creation-logo-preview');if(n)n.textContent=flowDraft.name||'Your guild name';if(d)d.textContent=flowDraft.description||'A shared ambition deserves a place to grow.';if(t)t.innerHTML=flowDraft.tags.map(v=>`<span>${escapeHtml(v)}</span>`).join('')||'<span>Your community</span>';if(img)img.src=flowDraft.logoData||'assets/'+flowDraft.logo+'.webp'}
function tradePreview(){open(`<div class="modal-eyebrow">CONTRIBUTE TO THE TEAM</div><h2>Every contribution starts with you.</h2><p>This design preview keeps the trade action in the guild journey. Trading, account eligibility and mission tracking will connect to the production exchange later.</p><div class="notice">No transaction or reward is created in this demo.</div><div class="modal-actions"><button class="secondary" data-close-flow>Keep exploring</button><a class="primary button" href="https://xox.exchange" target="_blank" rel="noopener">Visit XOX ${arrow()}</a></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-flow-next')){const f=$('#flow-create-form');if(!f.reportValidity())return;collectFlowDraft();if(flowStep===1&&(flowDraft.name.length<3||flowDraft.description.length<10)){toast('Add a guild name and a short description.');return}if(flowStep===1&&guilds().some(g=>g.name.toLowerCase()===flowDraft.name.toLowerCase())){toast('That guild name is in use. Try another.');return}flowStep++;renderRoute(false);$('#workspace .creation-form-panel')?.scrollIntoView({block:'start',behavior:'smooth'})}if(b.hasAttribute('data-flow-prev')){collectFlowDraft();flowStep=Math.max(1,flowStep-1);renderRoute(false)}if(b.dataset.flowLogo){flowDraft.logo=b.dataset.flowLogo;delete flowDraft.logoData;document.querySelectorAll('[data-flow-logo]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b))});updatePreview()}if(b.dataset.flowTag){const t=b.dataset.flowTag;flowDraft.tags=flowDraft.tags.includes(t)?flowDraft.tags.filter(x=>x!==t):[...flowDraft.tags,t];b.classList.toggle('selected',flowDraft.tags.includes(t));b.setAttribute('aria-pressed',String(flowDraft.tags.includes(t)));updatePreview()}if(b.dataset.entryPreset){const f=$('#flow-create-form');f.elements[b.dataset.entryPreset].value=b.dataset.value;collectFlowDraft()}if(b.dataset.missionTab){missionTab=b.dataset.missionTab;const ctx=memberContext();const g=ctx.g||guildById('unisat');$('#dashboard-missions').innerHTML=missionBoard(g,ctx.preview)}if(b.dataset.missionAction){const id=b.dataset.missionAction,g=guildById(b.dataset.contextGuild),preview=routeQuery.get('preview')==='1';if(id==='checkin'){if(preview||state.membership?.id!==g.id){toast('Join a demo guild to save a local check-in.');return}state.checkins[g.id]=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Hong_Kong'});save();toast('Local check-in saved. No rewards or points granted.')}else if(['community','referrals'].includes(id)){document.querySelector(`[data-share="${g.id}"]`)?.click();if(!document.querySelector(`[data-share="${g.id}"]`))toast('Use Invite your circle on the Dashboard to copy the guild link.')}else if(id==='ranking')navigate('rankings');else if(id==='consistency')navigate('my-guild/members'+previewSuffix(preview));else tradePreview()}if(b.hasAttribute('data-flow-trade'))tradePreview();if(b.hasAttribute('data-close-flow'))close();if(b.hasAttribute('data-battle-rules'))open(`<div class="modal-eyebrow">GUILD BATTLE · DEMO FORMAT</div><h2>A clear field for every team.</h2><ul><li>The sample match compares each team’s combined trading volume.</li><li>Shares and the gap are calculated from the same demonstration values.</li><li>Milestones illustrate collective progress.</li><li>Rewards, scoring and competition windows remain adjustable design parameters.</li></ul><div class="notice">No live match or reward commitment is connected to this prototype.</div><button class="primary" data-close-flow>Back to the match</button>`);if(b.hasAttribute('data-edit-pin')){const g=guildById(routePath.split('/')[1]);if(state.membership?.id!==g?.id||state.membership?.role!=='owner')return;open(`<div class="modal-eyebrow">SET THE DIRECTION</div><h2>A shared message for your team.</h2><form id="pin-form" class="form" data-id="${g.id}"><label for="pin-message">Pinned guild announcement</label><textarea id="pin-message" name="announcement" maxlength="1000" rows="4" required>${escapeHtml(g.announcement||'')}</textarea><div class="modal-actions"><button class="primary" type="submit">Save announcement</button></div></form>`)}});
document.addEventListener('input',e=>{if(e.target.closest('#flow-create-form')&&flowStep===1){collectFlowDraft();updatePreview()}});
document.addEventListener('change',async e=>{if(e.target.closest('#flow-create-form')&&e.target.name==='policy'){collectFlowDraft();document.querySelectorAll('.policy-option').forEach(el=>el.classList.toggle('chosen',el.querySelector('input').checked));const panel=document.querySelector('.creation-preview-details');if(panel)panel.lastElementChild.querySelector('strong').textContent=flowDraft.policy==='open'?'Instant join':'Approval required'}if(e.target.id==='guild-logo-upload'){const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){toast('Choose a PNG, JPG or WebP image up to 2 MB.');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{flowDraft.logoData=String(reader.result);document.querySelectorAll('[data-flow-logo]').forEach(el=>{el.classList.remove('selected');el.setAttribute('aria-pressed','false')});updatePreview()};reader.readAsDataURL(file)}});
document.addEventListener('submit',e=>{const form=e.target;if(form.id==='flow-create-form'){e.preventDefault();if(flowStep<3){form.querySelector('[data-flow-next]').click();return}collectFlowDraft();if(flowDraft.name.length<3||flowDraft.description.length<10){flowStep=1;renderRoute(false);toast('Add a guild name and a short description.');return}if(state.membership){toast('You already have a demo guild membership.');return}if(guilds().some(g=>g.name.toLowerCase()===flowDraft.name.toLowerCase())){toast('That guild name is in use.');return}const id='guild-'+Date.now();state.drafts.push({...flowDraft,id,tier:'New',level:1,isNew:true,volume:0,points:0,members:1,activity:0,style:flowDraft.tags.join(' · ')||'Community · All markets'});state.membership={id,name:state.profileName||'Guild Leader',role:'owner',created:true};state.wallet=true;save();showWelcome(guildById(id),true)}if(form.id==='flow-join-form'){e.preventDefault();const id=form.dataset.id,g=guildById(id),f=new FormData(form),name=f.get('name').trim();if(!name){toast('Enter your trader name.');return}if(state.membership){toast('You already have a demo guild membership.');return}state.profileName=name;state.wallet=true;if(g.policy==='approval'){if(!state.pending.includes(id))state.pending.push(id);save();open(`<div class="welcome-modal"><div class="modal-eyebrow">YOUR INTRODUCTION IS READY</div><div class="welcome-emblem"><img src="${emblem(g)}" alt=""></div><h2>A new connection.<br>A shared possibility.</h2><p>Your demo application to ${escapeHtml(g.name)} has been saved on this browser. No application has been sent to a guild leader.</p><span class="member-pill">${icon('clock')} Demo application saved</span><button class="primary" data-action="myguild">View my application ${arrow()}</button></div>`)}else{state.membership={id,name,role:'member',created:false};save();showWelcome(g)}}if(form.id==='forum-form'){e.preventDefault();const f=new FormData(form),text=String(f.get('message')||'').trim();if(!text)return;const id=form.dataset.id;if(!state.forums[id])state.forums[id]=[];state.forums[id].push({text:text.slice(0,2000),name:state.profileName||state.membership?.name||'Demo Trader',time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Hong_Kong'})});if(state.forums[id].length>100)state.forums[id].shift();save();$('#chat-scroll').scrollTop=$('#chat-scroll').scrollHeight;$('#chat-message').focus()}if(form.id==='flow-details-form'){e.preventDefault();const g=state.drafts.find(x=>x.id===form.dataset.id);if(!g||state.membership?.id!==g.id||state.membership?.role!=='owner')return;const f=new FormData(form);['rules','announcement','minVolume','minVip','minAssets'].forEach(k=>g[k]=String(f.get(k)||'').trim());save();toast('Community settings saved on this browser.')}if(form.id==='pin-form'){e.preventDefault();const g=state.drafts.find(x=>x.id===form.dataset.id);if(!g||state.membership?.id!==g.id||state.membership?.role!=='owner')return;g.announcement=String(new FormData(form).get('announcement')).trim();close();save();toast('Pinned announcement updated locally.')}});
document.addEventListener('keydown',e=>{if(e.target.id==='chat-message'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.form.requestSubmit()}});
// Restore the proper open action now that the full creation flow is loaded.

function battleContributors(g,volume){const ratios=[.24,.18,.14,.10];return `<div class="contributor-list">${roster(g).slice(0,4).map((m,i)=>`<div><span class="contributor-number">${String(i+1).padStart(2,'0')}</span><span class="avatar avatar-${i%4}">${escapeHtml(m.initial)}</span><div><strong>${escapeHtml(m.name)}</strong><small>${m.role}</small></div><span>${compactMoney(Math.round(volume*ratios[i]))}<small>MATCH VOLUME</small></span></div>`).join('')}</div>`}
